/*Table structure for table `questions` */

DROP TABLE IF EXISTS `questions`;

CREATE TABLE `questions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question` text NOT NULL,
  `option_a` varchar(255) NOT NULL,
  `option_b` varchar(255) NOT NULL,
  `option_c` varchar(255) NOT NULL,
  `option_d` varchar(255) NOT NULL,
  `correct_option` char(1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=latin1;

/*Data for the table `questions` */

insert  into `questions`(`id`,`question`,`option_a`,`option_b`,`option_c`,`option_d`,`correct_option`) values 
(1,'Apa kepanjangan dari GSM dalam dunia telekomunikasi?','Global System for Mobile Communications','General Satellite Module','Global Signal Management','General System for Mobile Operations','A'),
(2,'Apa fungsi utama dari BTS dalam jaringan seluler?','Menghubungkan pengguna langsung ke internet','Mengirim dan menerima sinyal dari perangkat seluler','Mengatur alamat IP pengguna','Menyimpan data pelanggan','B'),
(3,'Dalam teknologi 4G LTE, apa kepanjangan dari LTE?','Long Term Evolution','Limited Telecommunication Equipment','Local Transmission Efficiency','Linear Telecommunication Exchange','A');

/*Table structure for table `questions.bak` */

DROP TABLE IF EXISTS `questions.bak`;

CREATE TABLE `questions.bak` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question` text NOT NULL,
  `option_a` varchar(255) NOT NULL,
  `option_b` varchar(255) NOT NULL,
  `option_c` varchar(255) NOT NULL,
  `option_d` varchar(255) NOT NULL,
  `correct_option` char(1) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=latin1;

